begin;
create table public.settings (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() unique references auth.users(id) on delete cascade, confectionery_name text not null default 'D’ Gourmet', owner_name text default '', desired_monthly_income numeric not null default 0 check(desired_monthly_income>=0), productive_hours_per_month numeric not null default 0 check(productive_hours_per_month>=0), default_margin_pct numeric not null default 30 check(default_margin_pct>=0 and default_margin_pct<100), default_overhead_pct numeric not null default 0, overhead_base text not null default 'direct_costs', default_pricing_method text not null default 'margin', rounding_rule text not null default 'none', monthly_units_estimate numeric, currency text not null default 'BRL', report_prefs jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, kind text not null, name text not null, sort_order int not null default 99, created_at timestamptz not null default now(), unique(user_id,id), unique(user_id,kind,name));
create table public.sale_channels (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null, percent_fee numeric not null default 0 check(percent_fee>=0 and percent_fee<100), fixed_fee numeric not null default 0 check(fixed_fee>=0), is_default boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,id), unique(user_id,name));
create table public.ingredients (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null, category_id uuid, brand text, supplier text, purchase_quantity numeric not null check(purchase_quantity>0), purchase_unit text not null default 'g', total_price numeric not null check(total_price>=0), purchase_date date, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,id), foreign key(user_id,category_id) references public.categories(user_id,id));
create table public.packagings (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null, type text, category_id uuid, purchase_quantity numeric not null check(purchase_quantity>0), total_price numeric not null check(total_price>=0), supplier text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,id), foreign key(user_id,category_id) references public.categories(user_id,id));
create table public.recipes (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null, category_id uuid, description text, photo_url text, yield_quantity numeric not null default 0 check(yield_quantity>=0), sale_unit_label text not null default 'unidade', units_per_sale numeric not null default 1 check(units_per_sale>0), prep_minutes numeric not null default 0 check(prep_minutes>=0), extra_work_minutes numeric not null default 0 check(extra_work_minutes>=0), desired_margin_pct numeric not null default 30, pricing_method text not null default 'margin', markup_pct numeric, current_sale_price numeric, overhead_pct numeric, is_kit boolean not null default false, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,id), foreign key(user_id,category_id) references public.categories(user_id,id));
create table public.recipe_ingredients (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, recipe_id uuid not null, ingredient_id uuid not null, quantity numeric not null check(quantity>0), unit text not null, created_at timestamptz not null default now(), foreign key(user_id,recipe_id) references public.recipes(user_id,id) on delete cascade, foreign key(user_id,ingredient_id) references public.ingredients(user_id,id));
create table public.recipe_packagings (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, recipe_id uuid not null, packaging_id uuid not null, quantity numeric not null check(quantity>0), scope text not null default 'per_sale', created_at timestamptz not null default now(), foreign key(user_id,recipe_id) references public.recipes(user_id,id) on delete cascade, foreign key(user_id,packaging_id) references public.packagings(user_id,id));
create table public.recipe_costs (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, recipe_id uuid not null, label text not null, amount numeric not null check(amount>=0), kind text not null default 'batch', created_at timestamptz not null default now(), foreign key(user_id,recipe_id) references public.recipes(user_id,id) on delete cascade);
create table public.sale_variations (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, recipe_id uuid not null, name text not null, units_per_sale numeric not null default 1 check(units_per_sale>0), packaging_id uuid, packaging_quantity numeric not null default 1, packaging_scope text not null default 'per_sale', extra_cost numeric not null default 0, current_price numeric, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(user_id,recipe_id) references public.recipes(user_id,id) on delete cascade, foreign key(user_id,packaging_id) references public.packagings(user_id,id));
create table public.kit_items (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, parent_recipe_id uuid not null, component_recipe_id uuid not null, quantity numeric not null default 1 check(quantity>0), created_at timestamptz not null default now(), check(parent_recipe_id<>component_recipe_id), foreign key(user_id,parent_recipe_id) references public.recipes(user_id,id) on delete cascade, foreign key(user_id,component_recipe_id) references public.recipes(user_id,id));
create table public.expenses (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null, category_id uuid, type text not null default 'fixed', amount numeric not null check(amount>=0), periodicity text not null default 'monthly', description text, include_in_pricing boolean not null default true, allocation_basis text not null default 'per_unit', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(user_id,category_id) references public.categories(user_id,id));
create table public.ingredient_price_history (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, ingredient_id uuid not null, total_price numeric not null, purchase_quantity numeric not null, purchase_unit text not null, recorded_at timestamptz not null default now(), created_at timestamptz not null default now(), foreign key(user_id,ingredient_id) references public.ingredients(user_id,id) on delete cascade);
create table public.pricing_history (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, recipe_id uuid not null, cost_unit numeric, suggested_price numeric, sale_price numeric, margin_pct numeric, snapshot jsonb not null default '{}', created_at timestamptz not null default now(), foreign key(user_id,recipe_id) references public.recipes(user_id,id) on delete cascade);
do $$ declare t text; begin
 foreach t in array array['settings','categories','sale_channels','ingredients','packagings','recipes','recipe_ingredients','recipe_packagings','recipe_costs','sale_variations','kit_items','expenses','ingredient_price_history','pricing_history'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from anon',t);
 execute format('grant select,insert,update,delete on public.%I to authenticated',t);
 execute format('create policy own_select on public.%I for select to authenticated using ((select auth.uid())=user_id)',t);
 execute format('create policy own_insert on public.%I for insert to authenticated with check ((select auth.uid())=user_id)',t);
 execute format('create policy own_update on public.%I for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id)',t);
 execute format('create policy own_delete on public.%I for delete to authenticated using ((select auth.uid())=user_id)',t);
 execute format('create index %I on public.%I(user_id)',t||'_owner_idx',t);
 end loop; end $$;
create index on public.recipe_ingredients(recipe_id); create index on public.recipe_ingredients(ingredient_id);
create index on public.recipe_packagings(recipe_id); create index on public.recipe_packagings(packaging_id);
create index on public.recipe_costs(recipe_id); create index on public.sale_variations(recipe_id);
create index on public.kit_items(parent_recipe_id); create index on public.kit_items(component_recipe_id);
create index on public.ingredient_price_history(ingredient_id,recorded_at); create index on public.pricing_history(recipe_id,created_at);
create function public.initialize_workspace() returns void language plpgsql security invoker set search_path='' as $$
declare u uuid:=auth.uid(); inserted integer; begin
 if u is null then raise exception 'Authentication required'; end if;
 insert into public.settings(user_id) values(u) on conflict(user_id) do nothing;
 get diagnostics inserted=row_count;
 if inserted=0 then return; end if;
 insert into public.sale_channels(user_id,name,is_default) values(u,'Venda direta (Pix / dinheiro)',true) on conflict(user_id,name) do nothing;
 insert into public.categories(user_id,kind,name,sort_order) select u,x.kind,x.name,x.ord from (values
 ('recipe','Brigadeiros',1),('recipe','Docinhos',2),('recipe','Bolos',3),('recipe','Tortas',4),('recipe','Brownies',5),('recipe','Sobremesas',6),('recipe','Salgados',7),('recipe','Empadas',8),('recipe','Coxinhas',9),('recipe','Enroladinhos',10),('recipe','Kits',11),('recipe','Outros',12),
 ('ingredient','Laticínios',1),('ingredient','Chocolates e cacau',2),('ingredient','Farinhas e açúcares',3),('ingredient','Frutas',4),('ingredient','Carnes e frios',5),('ingredient','Ovos',6),('ingredient','Bebidas',7),('ingredient','Temperos e aditivos',8),('ingredient','Outros',9),
 ('packaging','Caixas',1),('packaging','Bandejas',2),('packaging','Sacolas',3),('packaging','Adesivos e fitas',4),('packaging','Forminhas',5),('packaging','Descartáveis',6),('packaging','Outros',7),
 ('expense','Estrutura',1),('expense','Administrativo',2),('expense','Matéria-prima',3),('expense','Embalagens',4),('expense','Taxas e comissões',5),('expense','Transporte',6),('expense','Outros',7)) as x(kind,name,ord) on conflict(user_id,kind,name) do nothing;
end $$;
revoke all on function public.initialize_workspace() from public,anon; grant execute on function public.initialize_workspace() to authenticated;
create function public.record_ingredient_price() returns trigger language plpgsql security invoker set search_path='' as $$ begin
 if tg_op='INSERT' or (new.total_price,new.purchase_quantity,new.purchase_unit) is distinct from (old.total_price,old.purchase_quantity,old.purchase_unit) then
 insert into public.ingredient_price_history(user_id,ingredient_id,total_price,purchase_quantity,purchase_unit) values(new.user_id,new.id,new.total_price,new.purchase_quantity,new.purchase_unit); end if; return new; end $$;
revoke all on function public.record_ingredient_price() from public,anon;
create trigger ingredient_history after insert or update on public.ingredients for each row execute function public.record_ingredient_price();
notify pgrst,'reload schema';
commit;

revoke execute on function public.rls_auto_enable() from public,anon,authenticated;
